  "claims": [
    {
      "claim": "Delpazolid, which shares the query's 2-oxazolidinone with CH2OH and 3-fluorophenyl, has an absolute oral bioavailability of 99.75% after an 800 mg oral dose versus IV in healthy humans.",
      "card_ids": ["C01","C10","C15","C24"]
    },
    {
      "claim": "Linezolid, another oxazolidinone, has almost 100% fasted oral bioavailability; a fasted 600 mg tablet gave a mean absolute bioavailability of 93.01 ± 23.34% versus IV.",
      "card_ids": ["C14","C25","C31"]
    },
    {
      "claim": "Rivaroxaban, an oxazolidinone-containing drug, is almost completely absorbed in humans after oral tablets, and Caco-2 data show high permeability with only weak efflux.",
      "card_ids": ["C51","C52","C64","C68"]
    },
    {
      "claim": "DA-7867, a close structural analog containing the same tetrazole-pyridine-fluorophenyl-oxazolidinone components, showed almost negligible hepatic first-pass in rats (comparable AUC after IV vs intraportal dosing) and negligible CYP-mediated metabolism; intestinal first-pass was about 21.8% at 10 mg/kg, still not a low-F barrier.",
      "card_ids": ["C77","C76","C74","C71"]
    },
    {
      "claim": "Multiple oxazolidinone analogs show low predicted human hepatic clearance in HLM (5.7–8.4 mL/min/kg), and rivaroxaban has low HLM intrinsic clearance (4.002 µL/min/mg), supporting low hepatic metabolic clearance for this scaffold.",
      "card_ids": ["C80","C72","C78","C70","C73","C75"]
    },
    {
      "claim": "Delpazolid's L3 oral exposure record shows AUC0-last of 18,636.27 ng·h/mL after 800 mg PO, consistent with substantial oral absorption.",
      "card_ids": ["C42"]
    },
    {
      "claim": "L5 bidirectional Caco-2 records for related compounds show high A→B permeability and efflux ratios near unity, providing no affirmative evidence of gut-wall efflux limitation for this chemotype.",
      "card_ids": ["C61","C60","C63","C62","C59","C65","C67"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
