      "card_ids": ["C80","C72","C78","C70","C73","C75"]
    },
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C69","C79"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the query molecule itself.",
    "No query-specific hepatic clearance or metabolic-stability data are available; L6 records are for close analogs and other molecules.",
    "DA-7867 hepatic first-pass data are from rats and differ at the oxazolidinone C5 substituent (acetamidomethyl vs hydroxymethyl) and pyridine substitution pattern.",
    "Dose and formulation for the query are unspecified; F can be dose- or formulation-dependent.",
    "No IV comparator or matched oral-versus-IV exposure data are available for the query.",
    "L6 records are mechanistic hepatic-clearance evidence, not direct oral-bioavailability outcomes or additional gold votes."
  ],
  "decision_summary": "Predicted high (F >= 20%) because the query is an oxazolidinone closely related to delpazolid (F ~99.75%) and linezolid (F ~93–100% fasted), with a favorable physicochemical prior; L6 hepatic-clearance records for DA-7867, which shares the tetrazole-pyridine-fluorophenyl-oxazolidinone scaffold, show negligible hepatic first-pass and CYP metabolism, and other oxazolidinone HLM records show low hepatic clearance, providing no affirmative evidence of F < 20%."
}

